dtsPropsFor.VerificationBadge:
/** One of the nine assessment values. */
assessment: 'false' | 'misleading' | 'manipulated' | 'out_of_context' | 'unsupported' | 'unverified' | 'contested' | 'satire' | 'verified';
confidence?: 'high' | 'medium' | 'limited';

dtsPropsFor.Timeline:
entries: Array<{
  /** Becomes the <li> DOM id, so /#entry-id deep links work. */
  id: string;
  /** Machine value for <time dateTime>, e.g. '2023-10-07'. */
  datetime: string;
  /** What the reader sees, e.g. '7 Oct 2023'. */
  dateLabel: string;
  title: string;
  body: React.ReactNode;
  region?: string;
  category?: string;
  assessment?: 'false' | 'misleading' | 'manipulated' | 'out_of_context' | 'unsupported' | 'unverified' | 'contested' | 'satire' | 'verified';
  sources?: Array<{ id: string; label: string; kind?: string; url?: string; accessedAt?: string; archiveUrl?: string }>;
}>;
/** feed: blue rail, news runs. history: gold rail, historical arcs.
 *  spread: ember rail with diamond markers, claim propagation. */
variant?: 'feed' | 'history' | 'spread';

dtsPropsFor.ContentCard:
/** Mono caps kicker above the title. */
eyebrow?: string;
title: string;
/** Mono caps meta line under the title. */
meta?: React.ReactNode;
children: React.ReactNode;
/** Ruled-off footer strip. */
footer?: React.ReactNode;
/** Colours the left border and eyebrow. 'ember' is the hostile register. */
accent?: 'gold' | 'ember';
/** Makes the whole card a link. */
href?: string;

dtsPropsFor.ClaimRecordPair:
claim: React.ReactNode;
record: React.ReactNode;
/** Default 'The claim'. */
claimLabel?: string;
/** Default 'The record'. */
recordLabel?: string;

dtsPropsFor.KnownUnknownPanel:
/** Bullets under 'Not established'. */
unknowns: string[];
/** Bullets under 'What would change the assessment'. Omit to collapse to one column. */
wouldChange?: string[];

dtsPropsFor.PublicationMeta:
publishedAt?: string;
updatedAt?: string;
coverageWindow?: string;
reviewedBy?: string;
/** Rendered as 'N sources'. */
sourceCount?: number;
/** e.g. 'Edition 04 · August 2026'. */
edition?: string;

dtsPropsFor.SensitiveContent:
/** Shown before reveal, under a 'Sensitive material' kicker. */
warning: string;
/** Part of the client bundle — keep serializable. */
children: React.ReactNode;

dtsPropsFor.ReadingProgress:
/** Substitute the host's own track treatment. */
trackClassName?: string;
valueClassName?: string;

dtsPropsFor.SectionToc:
/* No props. Builds itself from the rendered h2s inside [data-toc-source],
   and measures depth of read against the nearest [data-reading-scroll]
   ancestor. Renders nothing without both, or with fewer than two headings. */

dtsPropsFor.DesignSurface:
children?: React.ReactNode;
/** Inner padding. Defaults to a reading inset. */
pad?: React.CSSProperties['padding'];
/** Constrain to the 68ch reading measure the dossier pages use. */
measure?: boolean;
className?: string;
style?: React.CSSProperties;
